#pragma once

#include <vector>

#include <cube/solver/cube.hpp>

#include "cubie.hpp"

// The intermediate solver's last layer, as two table lookups. The tables are
// generated by tools/cfop_tables and checked in as cfop_case_words.inc; there
// is no search here, and every entry is the shortest sequence over <U, R, F>
// for its case.
//
// Both functions expect the first two layers already solved, and read only
// the four U-layer corners and edges (see cfop_case_index.hpp).

namespace cube::solver::detail {

// The moves that orient the whole last layer - every U-layer corner turned
// to show the top colour, every U-layer edge flipped to - or nullptr if the
// table has no usable entry (which a valid cube never reaches).
[[nodiscard]] const std::vector<Move>* oll_algorithm(const CubieCube& cube) noexcept;

// The moves that put an already-oriented last layer's pieces where they
// belong, finishing the cube, or nullptr if `cube`'s last layer is not
// oriented or its corner and edge parities disagree (a real cube's never do).
[[nodiscard]] const std::vector<Move>* pll_algorithm(const CubieCube& cube) noexcept;

}  // namespace cube::solver::detail
